-- ============================================================
--  009_denominaciones_cno_descripcion
--
--  Carga la DESCRIPCIÓN real de las denominaciones CNO desde el catálogo
--  oficial "2CNO_2024_(2025-06-13).xlsx", hoja «Denominaciones - C.N.O.».
--
--  Por qué: al cargar el catálogo se copió el CÓDIGO dentro de la columna de
--  descripción. En base, 9.931 de 10.036 filas de `cno_denominacion` tenían
--  `desc_denominacion = cod_denominacion_cno`, es decir "D-0011.001" donde
--  debía decir "Alcalde". Se notaba en Validación Experta y en Comparativa,
--  que mostraban el código dos veces en vez del nombre de la denominación.
--  En CUOC no ocurre: de sus 14.833 filas, ninguna repite el código.
--
--  Alcance: solo filas cuya descripción es HOY igual a su código. Si alguien
--  ya escribió una descripción de verdad —propia o de una copia de análisis—
--  no se toca. Las denominaciones de copias ("0112-14-D1") no están en el
--  catálogo oficial y por tanto quedan fuera por construcción.
--
--  Idempotente: al segundo pase ninguna fila cumple ya la condición.
--
--  NO lleva BEGIN/COMMIT: el runner (scripts/db-migrate.js) envuelve cada
--  archivo en su propia transacción.
-- ============================================================

CREATE TEMP TABLE tmp_den_cno (cod text PRIMARY KEY, descripcion text NOT NULL) ON COMMIT DROP;

